    /** GOBACK, STOP RUN or EXIT PROGRAM: the program ends, from however deep. */
    private static final class CocoonStop extends RuntimeException {
        CocoonStop() {
            super(null, null, false, false);
        }
    }

    /** GO TO: the paragraph control goes to next; the runner continues there. */
    private static final class CocoonGoTo extends RuntimeException {
        final int to;

        CocoonGoTo(int to) {
            super(null, null, false, false);
            this.to = to;
        }
    }

    private static final CocoonStop COCOON_STOP = new CocoonStop();

    private static void cocoonStop() {
        throw COCOON_STOP;
    }

    private static void cocoonGoTo(int to) {
        throw new CocoonGoTo(to);
    }

    // Index names (INDEXED BY): occurrence numbers, counted from one.
    private int wwmIndx = 1;   // WWM-INDX, of WWM-ENTRY
    private int dx5 = 1;   // DX5, of DRGX-PERIOD
    private int dx6 = 1;   // DX6, of DRG-DATA
    private int ssrfbnIdx = 1;   // SSRFBN-IDX, of SSRFBN-TAB

    public void run() {
        try {
            cocoonPerform(0, 36);
        } catch (CocoonStop s) {
            // GOBACK, STOP RUN or EXIT PROGRAM: the program ends
        }
    }

    /**
     * PERFORM from THRU thru: the paragraphs in order from the first to
     * the end of the last, falling through as COBOL does, and following
     * every GO TO wherever it leads - within the range or beyond it.
     */
    private void cocoonPerform(int from, int thru) {
        int p = from;
        while (true) {
            try {
                cocoonParagraph(p);
            } catch (CocoonGoTo g) {
                p = g.to;
                continue;
            }
            if (p == thru) {
                return;
            }
            p++;
            if (p >= 37) {
                throw COCOON_STOP;   // the end of the program
            }
        }
    }

    private void cocoonParagraph(int p) {
        switch (p) {
            case 0: p0000MainlineControl(); return;   // 0000-MAINLINE-CONTROL
            case 1: p0100InitialRoutine(); return;   // 0100-INITIAL-ROUTINE
            case 2: p0100Exit(); return;   // 0100-EXIT
            case 3: p1000EditTheBillInfo(); return;   // 1000-EDIT-THE-BILL-INFO
            case 4: p1000Exit(); return;   // 1000-EXIT
            case 5: p1200DaysUsed(); return;   // 1200-DAYS-USED
            case 6: p1200DaysUsedExit(); return;   // 1200-DAYS-USED-EXIT
            case 7: p1700EditDrgCode(); return;   // 1700-EDIT-DRG-CODE
            case 8: p1700Exit(); return;   // 1700-EXIT
            case 9: p1750FindValue(); return;   // 1750-FIND-VALUE
            case 10: p1750Exit(); return;   // 1750-EXIT
            case 11: p1800EditIppsDrgCode(); return;   // 1800-EDIT-IPPS-DRG-CODE
            case 12: p1800Exit(); return;   // 1800-EXIT
            case 13: p1900ApplySsrfbn(); return;   // 1900-APPLY-SSRFBN
            case 14: p1900Exit(); return;   // 1900-EXIT
            case 15: p1950FindSsrfbn(); return;   // 1950-FIND-SSRFBN
            case 16: p1950Exit(); return;   // 1950-EXIT
            case 17: p2000AssemblePpsVariables(); return;   // 2000-ASSEMBLE-PPS-VARIABLES
            case 18: p2000Exit(); return;   // 2000-EXIT
            case 19: p3000CalcPayment(); return;   // 3000-CALC-PAYMENT
            case 20: p3000Exit(); return;   // 3000-EXIT
            case 21: p3400ShortStay(); return;   // 3400-SHORT-STAY
            case 22: p3400ShortStayExit(); return;   // 3400-SHORT-STAY-EXIT
            case 23: p3600SsBlendedPmt(); return;   // 3600-SS-BLENDED-PMT
            case 24: p3600SsBlendedPmtExit(); return;   // 3600-SS-BLENDED-PMT-EXIT
            case 25: p3650SsIppsCompPmt(); return;   // 3650-SS-IPPS-COMP-PMT
            case 26: p3650SsIppsCompPmtExit(); return;   // 3650-SS-IPPS-COMP-PMT-EXIT
            case 27: p3675SsIppsCompPrPmt(); return;   // 3675-SS-IPPS-COMP-PR-PMT
            case 28: p3675Exit(); return;   // 3675-EXIT
            case 29: p4000SpecialProvider(); return;   // 4000-SPECIAL-PROVIDER
            case 30: p4000SpecialProviderExit(); return;   // 4000-SPECIAL-PROVIDER-EXIT
            case 31: p7000CalcOutlier(); return;   // 7000-CALC-OUTLIER
            case 32: p7000Exit(); return;   // 7000-EXIT
            case 33: p8000Blend(); return;   // 8000-BLEND
            case 34: p8000Exit(); return;   // 8000-EXIT
            case 35: p9000MoveResults(); return;   // 9000-MOVE-RESULTS
            case 36: p9000Exit(); return;   // 9000-EXIT
            default: throw COCOON_STOP;
        }
    }

    /** 0000-MAINLINE-CONTROL */
    private void p0000MainlineControl() {
        cocoonPerform(1, 2);   // PERFORM 0100-INITIAL-ROUTINE THRU 0100-EXIT
        cocoonPerform(3, 4);   // PERFORM 1000-EDIT-THE-BILL-INFO THRU 1000-EXIT
        if (ppsRtc.value().compareTo(new BigDecimal("00")) == 0) {
            cocoonPerform(7, 8);   // PERFORM 1700-EDIT-DRG-CODE THRU 1700-EXIT
        }
        if (ppsRtc.value().compareTo(new BigDecimal("00")) == 0) {
            dx5 = 1;
            while (!(BigDecimal.valueOf(dx5).compareTo(new BigDecimal("1")) > 0)) {
                cocoonPerform(11, 12);   // PERFORM 1800-EDIT-IPPS-DRG-CODE THRU 1800-EXIT
                dx5 += 1;
            }
        }
        if (ppsRtc.value().compareTo(new BigDecimal("00")) == 0) {
            cocoonPerform(17, 18);   // PERFORM 2000-ASSEMBLE-PPS-VARIABLES THRU 2000-EXIT
        }
        if (ppsRtc.value().compareTo(new BigDecimal("00")) == 0) {
            cocoonPerform(19, 20);   // PERFORM 3000-CALC-PAYMENT THRU 3000-EXIT
            cocoonPerform(31, 32);   // PERFORM 7000-CALC-OUTLIER THRU 7000-EXIT
        }
        if (ppsRtc.value().compareTo(new BigDecimal("50")) < 0) {
            cocoonPerform(33, 34);   // PERFORM 8000-BLEND THRU 8000-EXIT
        }
        cocoonPerform(35, 36);   // PERFORM 9000-MOVE-RESULTS THRU 9000-EXIT
        cocoonStop();   // GOBACK
    }

